SELECT draft_generation, id, provider_id, global_id, thread_id, provider_thread_id, replying_to_id, link_id, provider_history_id, internal_date_ts, snippet, size_estimate, subject, from_name, from_contact_id, sent_at, has_attachments, is_read, is_starred, is_sent, is_draft, headers_jsonb, created_at, updated_at, -- No body attributes body_text as body_text, body_html_sanitized as body_html_sanitized, NULL::TEXT as body_macro FROM email_messages WHERE thread_id = $1 AND NOT (is_draft AND COALESCE((mailbox_state->>'provider_missing')::boolean, false)) ORDER BY internal_date_ts DESC NULLS LAST LIMIT $2 OFFSET $3
